/** Per-submission limits for a resumable command-graph execution. */
export type GPUCommandGraphExecutionBudget = {
  /** Maximum statically estimated shader invocations encoded in one step. */
  maximumInvocationCount: number;
  /** Optional hard cap on graph nodes encoded in one step. */
  maximumNodeCount?: number;
  /** Optional hard cap on commands encoded in one step. */
  maximumCommandCount?: number;
  /** Optional upper bound on bytes read by nodes encoded in one step. */
  maximumReadByteLength?: number;
  /** Optional upper bound on bytes written by nodes encoded in one step. */
  maximumWriteByteLength?: number;
};

/** Scheduling urgency attached to a resumable graph invocation. */
export type GPUCommandGraphExecutionLatencyPriority = 'interactive' | 'normal' | 'background';

/** Whether intermediate coherent-result boundaries should become separate publication steps. */
export type GPUCommandGraphExecutionPublicationPolicy = 'final' | 'progressive';

/** Scheduling policy for one immutable resumable execution plan. */
export type GPUCommandGraphExecutionOptions = {
  /** Urgency exposed to application schedulers and adaptive budget controllers. Default `normal`. */
  latencyPriority?: GPUCommandGraphExecutionLatencyPriority;
  /** Whether declared intermediate result boundaries should be surfaced. Default `final`. */
  publicationPolicy?: GPUCommandGraphExecutionPublicationPolicy;
};

/** Static workload totals for one dependency-ordered execution-plan step. */
export type GPUCommandGraphExecutionPlanStep = {
  /** Zero-based step index. */
  stepIndex: number;
  /** First scheduled node included in this step. */
  firstNodeIndex: number;
  /** Scheduled node index immediately after this step. */
  nextNodeIndex: number;
  /** Number of scheduled nodes included in this step. */
  nodeCount: number;
  /** Sum of direct and indirect commands annotated for this step. */
  commandCount: number;
  /** Sum of static shader-invocation bounds for this step. */
  maximumInvocationCount: number;
  /** Sum of static read-byte bounds for this step. */
  readByteLength: number;
  /** Sum of static write-byte bounds for this step. */
  writeByteLength: number;
  /** Number of conditionally executed nodes in this step. */
  conditionalNodeCount: number;
  /** Whether one indivisible node exceeds at least one requested budget. */
  exceedsBudget: boolean;
  /** Scheduling urgency inherited from the execution plan. */
  latencyPriority: GPUCommandGraphExecutionLatencyPriority;
  /** Coherent results that become safe after this step completes on the GPU queue. */
  publications: readonly Readonly<GPUCommandGraphNodePublication>[];
  /** Whether an application may publish new results after this step completes. */
  publishable: boolean;
};

/** Immutable dry-run plan for one resumable graph invocation. */
export type GPUCommandGraphExecutionPlan = {
  /** Total number of scheduled nodes. */
  nodeCount: number;
  /** Number of nodes carrying at least one workload estimate. */
  annotatedNodeCount: number;
  /** Number of nodes controlled by CPU or GPU state. */
  conditionalNodeCount: number;
  /** Number of bounded queue submissions required by the static plan. */
  stepCount: number;
  /** Sum of commands across the complete graph. */
  commandCount: number;
  /** Sum of shader-invocation upper bounds across the complete graph. */
  maximumInvocationCount: number;
  /** Sum of read-byte upper bounds across the complete graph. */
  readByteLength: number;
  /** Sum of write-byte upper bounds across the complete graph. */
  writeByteLength: number;
  /** Number of indivisible steps exceeding at least one requested budget. */
  oversizedStepCount: number;
  /** Scheduling urgency attached to every step. */
  latencyPriority: GPUCommandGraphExecutionLatencyPriority;
  /** Intermediate-result publication policy used to create this plan. */
  publicationPolicy: GPUCommandGraphExecutionPublicationPolicy;
  /** Number of declared coherent results surfaced by planned steps. */
  publicationCount: number;
  /** Dependency-ordered submission steps. */
  steps: readonly Readonly<GPUCommandGraphExecutionPlanStep>[];
};

/** Result of encoding one bounded step of a resumable command-graph execution. */
export type GPUCommandGraphExecutionStep = GPUCommandGraphExecutionPlanStep & {
  /** Encoding statistics for the nodes recorded by this step. */
  encoding: GPUCommandGraphEncoding;
  /** Fraction of scheduled nodes encoded so far. */
  progress: number;
  /** Whether every graph node has now been encoded exactly once. */
  completed: boolean;
  /** Fraction of planned submissions covered by the most recent safe publication. */
  publishedProgress: number;
};

type EncodeGPUCommandGraphNodeRange<Parameters> = (
  commandEncoder: CommandEncoder,
  options: GPUCommandGraphEncodeOptions<Parameters>,
  firstNodeIndex: number,
  nextNodeIndex: number
) => GPUCommandGraphEncoding;

/**
 * Cursor over one dependency-ordered graph execution.
 *
 * Each call records a contiguous node range whose annotated invocation bounds fit the requested
 * budget. A node remains atomic, so operations opt into finer scheduling by contributing bounded
 * partition nodes. Submitting steps to the same device queue preserves graph order across frames.
 */
export class GPUCommandGraphExecution<Parameters = void> {
  /** Total number of scheduled graph nodes in this execution. */
  readonly nodeCount: number;
  /** Per-step scheduling budget. */
  readonly budget: Readonly<GPUCommandGraphExecutionBudget>;
  /** Immutable dry-run plan used by this execution. */
  readonly plan: Readonly<GPUCommandGraphExecutionPlan>;

  private readonly encodeNodeRange: EncodeGPUCommandGraphNodeRange<Parameters>;
  private nextStepIndex = 0;
  private currentPublishedProgress = 0;

  /** @internal */
  constructor(props: {
    plan: GPUCommandGraphExecutionPlan;
    budget: GPUCommandGraphExecutionBudget;
    encodeNodeRange: EncodeGPUCommandGraphNodeRange<Parameters>;
  }) {
    validateGPUCommandGraphExecutionBudget(props.budget);
    this.plan = props.plan;
    this.nodeCount = props.plan.nodeCount;
    this.budget = Object.freeze({...props.budget});
    this.encodeNodeRange = props.encodeNodeRange;
  }

  /** Whether every scheduled node has been encoded. */
  get completed(): boolean {
    return this.nextStepIndex >= this.plan.stepCount;
  }

  /** Fraction of scheduled nodes already encoded. */
  get progress(): number {
    return this.plan.stepCount === 0 ? 1 : this.nextStepIndex / this.plan.stepCount;
  }

  /** Fraction of planned submissions whose results have reached a declared safe boundary. */
  get publishedProgress(): number {
    return this.currentPublishedProgress;
  }

  /** Records the next dependency-ordered step without finishing or submitting its encoder. */
  encodeNext(
    commandEncoder: CommandEncoder,
    options: GPUCommandGraphEncodeOptions<Parameters>
  ): GPUCommandGraphExecutionStep {
    if (this.completed) {
      throw new Error('GPUCommandGraph execution has already completed');
    }
    const plannedStep = this.plan.steps[this.nextStepIndex];
    const encoding = this.encodeNodeRange(
      commandEncoder,
      options,
      plannedStep.firstNodeIndex,
      plannedStep.nextNodeIndex
    );
    this.nextStepIndex++;
    if (plannedStep.publishable) this.currentPublishedProgress = this.progress;
    return {
      ...plannedStep,
      encoding,
      progress: this.progress,
      completed: this.completed,
      publishedProgress: this.publishedProgress
    };
  }
}

type GPUCommandGraphExecutionCost = {
  nodeCount: number;
  commandCount: number;
  maximumInvocationCount: number;
  readByteLength: number;
  writeByteLength: number;
  conditionalNodeCount: number;
};

/** Creates a device-independent bounded-submission plan from one compiled graph preflight. */
export function getGPUCommandGraphExecutionPlan(
  preflight: Pick<GPUCommandGraphPreflightReport, 'nodes' | 'annotatedNodeCount'>,
  budget: GPUCommandGraphExecutionBudget,
  options: GPUCommandGraphExecutionOptions = {}
): GPUCommandGraphExecutionPlan {
  validateGPUCommandGraphExecutionBudget(budget);
  const latencyPriority = options.latencyPriority ?? 'normal';
  const publicationPolicy = options.publicationPolicy ?? 'final';
  if (!['interactive', 'normal', 'background'].includes(latencyPriority)) {
    throw new Error(`GPUCommandGraph execution latency priority "${latencyPriority}" is invalid`);
  }
  if (!['final', 'progressive'].includes(publicationPolicy)) {
    throw new Error(
      `GPUCommandGraph execution publication policy "${publicationPolicy}" is invalid`
    );
  }
  const nodes = preflight.nodes;
  const steps: Readonly<GPUCommandGraphExecutionPlanStep>[] = [];
  let nextNodeIndex = 0;
  while (nextNodeIndex < nodes.length) {
    const firstNodeIndex = nextNodeIndex;
    let cost = getEmptyGPUCommandGraphExecutionCost();
    while (nextNodeIndex < nodes.length) {
      const nextCost = addGPUCommandGraphExecutionCost(cost, nodes[nextNodeIndex]);
      if (
        nextNodeIndex > firstNodeIndex &&
        exceedsGPUCommandGraphExecutionBudget(nextCost, budget)
      ) {
        break;
      }
      cost = nextCost;
      nextNodeIndex++;
      if (publicationPolicy === 'progressive' && nodes[nextNodeIndex - 1].publication) break;
      if (reachesGPUCommandGraphExecutionBudget(cost, budget)) break;
    }
    const publications =
      publicationPolicy === 'progressive'
        ? Object.freeze(
            nodes
              .slice(firstNodeIndex, nextNodeIndex)
              .flatMap(node => (node.publication ? [node.publication] : []))
          )
        : Object.freeze([] as Readonly<GPUCommandGraphNodePublication>[]);
    const completed = nextNodeIndex === nodes.length;
    steps.push(
      Object.freeze({
        stepIndex: steps.length,
        firstNodeIndex,
        nextNodeIndex,
        ...cost,
        exceedsBudget: exceedsGPUCommandGraphExecutionBudget(cost, budget),
        latencyPriority,
        publications,
        publishable: completed || publications.length > 0
      })
    );
  }
  const totalCost = nodes.reduce(
    (cost, node) => addGPUCommandGraphExecutionCost(cost, node),
    getEmptyGPUCommandGraphExecutionCost()
  );
  return Object.freeze({
    ...totalCost,
    annotatedNodeCount: preflight.annotatedNodeCount,
    stepCount: steps.length,
    oversizedStepCount: steps.filter(step => step.exceedsBudget).length,
    latencyPriority,
    publicationPolicy,
    publicationCount: steps.reduce((count, step) => count + step.publications.length, 0),
    steps: Object.freeze(steps)
  });
}

function getEmptyGPUCommandGraphExecutionCost(): GPUCommandGraphExecutionCost {
  return {
    nodeCount: 0,
    commandCount: 0,
    maximumInvocationCount: 0,
    readByteLength: 0,
    writeByteLength: 0,
    conditionalNodeCount: 0
  };
}

function addGPUCommandGraphExecutionCost(
  cost: GPUCommandGraphExecutionCost,
  node: GPUCommandGraphNodePreflight
): GPUCommandGraphExecutionCost {
  return {
    nodeCount: cost.nodeCount + 1,
    commandCount: cost.commandCount + node.commandCount,
    maximumInvocationCount: cost.maximumInvocationCount + node.maximumInvocationCount,
    readByteLength: cost.readByteLength + node.readByteLength,
    writeByteLength: cost.writeByteLength + node.writeByteLength,
    conditionalNodeCount: cost.conditionalNodeCount + (node.condition ? 1 : 0)
  };
}

function exceedsGPUCommandGraphExecutionBudget(
  cost: GPUCommandGraphExecutionCost,
  budget: GPUCommandGraphExecutionBudget
): boolean {
  return (
    cost.maximumInvocationCount > budget.maximumInvocationCount ||
    (budget.maximumNodeCount !== undefined && cost.nodeCount > budget.maximumNodeCount) ||
    (budget.maximumCommandCount !== undefined && cost.commandCount > budget.maximumCommandCount) ||
    (budget.maximumReadByteLength !== undefined &&
      cost.readByteLength > budget.maximumReadByteLength) ||
    (budget.maximumWriteByteLength !== undefined &&
      cost.writeByteLength > budget.maximumWriteByteLength)
  );
}

function reachesGPUCommandGraphExecutionBudget(
  cost: GPUCommandGraphExecutionCost,
  budget: GPUCommandGraphExecutionBudget
): boolean {
  return (
    cost.maximumInvocationCount >= budget.maximumInvocationCount ||
    (budget.maximumNodeCount !== undefined && cost.nodeCount >= budget.maximumNodeCount) ||
    (budget.maximumCommandCount !== undefined && cost.commandCount >= budget.maximumCommandCount) ||
    (budget.maximumReadByteLength !== undefined &&
      cost.readByteLength >= budget.maximumReadByteLength) ||
    (budget.maximumWriteByteLength !== undefined &&
      cost.writeByteLength >= budget.maximumWriteByteLength)
  );
}

function validateGPUCommandGraphExecutionBudget(budget: GPUCommandGraphExecutionBudget): void {
  const limits = [
    ['maximumInvocationCount', budget.maximumInvocationCount],
    ['maximumNodeCount', budget.maximumNodeCount],
    ['maximumCommandCount', budget.maximumCommandCount],
    ['maximumReadByteLength', budget.maximumReadByteLength],
    ['maximumWriteByteLength', budget.maximumWriteByteLength]
  ] as const;
  for (const [name, value] of limits) {
    if (value !== undefined && (!Number.isSafeInteger(value) || value <= 0)) {
      throw new Error(`GPUCommandGraph execution ${name} must be a positive safe integer`);
    }
  }
}

