import {GPUPlanningHeap} from './gpu-planning-heap';
import {Buffer, PipelineFactory, Texture, textureFormatDecoder} from '@luma.gl/core';
import type {Device, TextureFormat} from '@luma.gl/core';
import type {
  GPUCommandGraphComputeExecutable,
  GPUCommandGraphCopyExecutable,
  GPUCommandGraphNode,
  GPUCommandGraphPreflightReport,
  GPUCommandGraphCompileOptions,
  GPUCommandGraphRenderExecutable,
  GPUCommandGraphStats,
  GPUCommandGraphResourceSummary,
  GraphBufferHandle,
  GraphBufferUsage,
  GraphBufferUse,
  GraphDataView,
  GraphExternalTextureHandle,
  GraphResourceUse,
  GraphTextureAspect,
  GraphTextureDimension,
  GraphTextureHandle,
  GraphTextureUse,
  GraphTextureUsage,
  GraphTextureView
} from './gpu-command-graph-types';

/** A graph node paired with the reusable executable produced by its compile callback. @internal */
export type CompiledNode<Parameters> = {
  /** Scheduled node definition. */
  node: GPUCommandGraphNode<Parameters>;
  /** Reusable node state and encode callback. */
  executable:
    | GPUCommandGraphComputeExecutable<Parameters>
    | GPUCommandGraphRenderExecutable<Parameters>
    | GPUCommandGraphCopyExecutable<Parameters>;
};

/** One physical buffer allocation shared by logical transients with disjoint lifetimes. @internal */
export type BufferTransientAllocation = {
  /** Maximum capacity required by any assigned handle. */
  byteLength: number;
  /** Union of usage flags required by assigned handles. */
  usage: number;
  /** Last scheduled node index using the most recently assigned handle. */
  lastUse: number;
  /** Logical handles assigned to this allocation in lifetime order. */
  handles: GraphBufferHandle[];
  /** Physical buffer created during compilation. */
  buffer?: Buffer;
};

type TransientTextureDescriptor = {
  id: string;
  format: TextureFormat;
  width: number;
  height: number;
  usage: number;
  dimension: GraphTextureDimension;
  depth: number;
  mipLevels: number;
  samples: number;
};

/** One physical texture allocation shared by compatible transients with disjoint lifetimes. @internal */
export type TextureTransientAllocation = {
  /** Descriptor shared by every assigned handle, with their usage flags combined. */
  descriptor: TransientTextureDescriptor;
  /** Estimated physical allocation size used for statistics. */
  byteLength: number;
  /** Last scheduled node index using the most recently assigned handle. */
  lastUse: number;
  /** Logical handles assigned to this allocation in lifetime order. */
  handles: GraphTextureHandle[];
  /** Physical texture created during compilation. */
  texture?: Texture;
};

/** Complete immutable input for constructing a `CompiledGPUCommandGraph`. @internal */
export type GPUCommandGraphCompilation<Parameters> = {
  /** Device owning compiled resources. */
  device: Device;
  /** Graph identifier. */
  id: string;
  /** Snapshot of logical buffer resources. */
  buffers: Map<string, GraphBufferHandle>;
  /** Snapshot of logical texture resources. */
  textures: Map<string, GraphTextureHandle>;
  /** Snapshot of logical frame-scoped external-image resources. */
  externalTextures: Map<string, GraphExternalTextureHandle>;
  /** Nodes and executables in stable topological order. */
  compiledNodes: CompiledNode<Parameters>[];
  /** Logical-to-physical transient buffer mapping. */
  transientBuffers: Map<GraphBufferHandle, Buffer>;
  /** Logical-to-physical transient texture mapping. */
  transientTextures: Map<GraphTextureHandle, Texture>;
  /** Physical buffer allocation plan retained for destruction. */
  bufferTransientAllocations: BufferTransientAllocation[];
  /** Physical texture allocation plan retained for destruction. */
  textureTransientAllocations: TextureTransientAllocation[];
  /** Scheduling and allocation statistics. */
  stats: GPUCommandGraphStats;
  /** Static resource and workload report for application-defined soft sanity checks. */
  preflight: GPUCommandGraphPreflightReport;
};

type GPUCommandGraphCompilerProps<Parameters> = {
  device: Device;
  id: string;
  buffers: Map<string, GraphBufferHandle>;
  textures: Map<string, GraphTextureHandle>;
  externalTextures: Map<string, GraphExternalTextureHandle>;
  nodes: GPUCommandGraphNode<Parameters>[];
  kernelMetadata?: GPUCommandGraphCompileOptions['kernelMetadata'];
};

/**
 * Compiles scheduling, transient allocations, and executable node resources.
 *
 * Compilation proceeds in four phases: infer a stable topological node order, plan allocation
 * reuse from transient lifetimes, create physical resources, then invoke node compile callbacks.
 * If allocation or a callback fails, every executable and physical resource created so far is
 * destroyed before the error is rethrown.
 *
 * @internal
 */
export function compileGPUCommandGraph<Parameters>(
  props: GPUCommandGraphCompilerProps<Parameters>
): GPUCommandGraphCompilation<Parameters> {
  const nodeOrder = getNodeOrder(props.nodes);
  const bufferPlan = getBufferTransientAllocationPlan(nodeOrder, props.buffers.values());
  const texturePlan = getTextureTransientAllocationPlan(nodeOrder, props.textures.values());
  const transientBuffers = new Map<GraphBufferHandle, Buffer>();
  const transientTextures = new Map<GraphTextureHandle, Texture>();

  const compiledNodes: CompiledNode<Parameters>[] = [];
  try {
    for (const allocation of bufferPlan) {
      allocation.buffer = props.device.createBuffer({
        id: `${props.id}-transient-buffer-${bufferPlan.indexOf(allocation)}`,
        byteLength: allocation.byteLength,
        usage: allocation.usage
      });
      for (const handle of allocation.handles) {
        transientBuffers.set(handle, allocation.buffer);
      }
    }
    for (const allocation of texturePlan) {
      allocation.texture = props.device.createTexture({
        ...allocation.descriptor,
        id: `${props.id}-transient-texture-${texturePlan.indexOf(allocation)}`
      });
      for (const handle of allocation.handles) {
        transientTextures.set(handle, allocation.texture);
      }
    }

    for (const node of nodeOrder) {
      compiledNodes.push({node, executable: node.compile({device: props.device})});
    }
  } catch (error) {
    for (const compiledNode of compiledNodes) {
      compiledNode.executable.destroy?.();
    }
    for (const allocation of bufferPlan) {
      allocation.buffer?.destroy();
    }
    for (const allocation of texturePlan) {
      allocation.texture?.destroy();
    }
    throw error;
  }

  return finishGPUCommandGraphCompilation(
    props,
    nodeOrder,
    compiledNodes,
    transientBuffers,
    transientTextures,
    bufferPlan,
    texturePlan
  );
}

/**
 * Compiles graph node resources concurrently through their asynchronous compilation callbacks.
 *
 * Scheduling and transient allocation remain deterministic and synchronous. All node compilation
 * promises are started before any is awaited, allowing WebGPU pipeline compilation to overlap.
 * Nodes without an asynchronous callback retain their synchronous compatibility path.
 *
 * @internal
 */
export async function compileGPUCommandGraphAsync<Parameters>(
  props: GPUCommandGraphCompilerProps<Parameters>
): Promise<GPUCommandGraphCompilation<Parameters>> {
  const nodeOrder = getNodeOrder(props.nodes);
  const bufferPlan = getBufferTransientAllocationPlan(nodeOrder, props.buffers.values());
  const texturePlan = getTextureTransientAllocationPlan(nodeOrder, props.textures.values());
  const transientBuffers = new Map<GraphBufferHandle, Buffer>();
  const transientTextures = new Map<GraphTextureHandle, Texture>();

  try {
    for (const allocation of bufferPlan) {
      allocation.buffer = props.device.createBuffer({
        id: `${props.id}-transient-buffer-${bufferPlan.indexOf(allocation)}`,
        byteLength: allocation.byteLength,
        usage: allocation.usage
      });
      for (const handle of allocation.handles) {
        transientBuffers.set(handle, allocation.buffer);
      }
    }
    for (const allocation of texturePlan) {
      allocation.texture = props.device.createTexture({
        ...allocation.descriptor,
        id: `${props.id}-transient-texture-${texturePlan.indexOf(allocation)}`
      });
      for (const handle of allocation.handles) {
        transientTextures.set(handle, allocation.texture);
      }
    }

    const asyncPipelineCompilation = PipelineFactory.beginAsyncCompilation(props.device);
    const nodeCompilationPromises = nodeOrder.map(async node => ({
      node,
      executable: node.compileAsync
        ? await node.compileAsync({device: props.device})
        : node.compile({device: props.device})
    }));
    PipelineFactory.endAsyncCompilation(props.device, asyncPipelineCompilation);
    const [results, pipelineResults] = await Promise.all([
      Promise.allSettled(nodeCompilationPromises),
      Promise.allSettled(asyncPipelineCompilation)
    ]);
    const compiledNodes: CompiledNode<Parameters>[] = [];
    const pipelineFailure = pipelineResults.find(result => result.status === 'rejected');
    let compilationError: unknown =
      pipelineFailure?.status === 'rejected' ? pipelineFailure.reason : undefined;
    for (const result of results) {
      if (result.status === 'fulfilled') {
        compiledNodes.push(result.value);
      } else {
        compilationError ??= result.reason;
      }
    }
    if (compilationError) {
      for (const compiledNode of compiledNodes) {
        compiledNode.executable.destroy?.();
      }
      throw compilationError;
    }

    return finishGPUCommandGraphCompilation(
      props,
      nodeOrder,
      compiledNodes,
      transientBuffers,
      transientTextures,
      bufferPlan,
      texturePlan
    );
  } catch (error) {
    for (const allocation of bufferPlan) {
      allocation.buffer?.destroy();
    }
    for (const allocation of texturePlan) {
      allocation.texture?.destroy();
    }
    throw error;
  }
}

function finishGPUCommandGraphCompilation<Parameters>(
  props: GPUCommandGraphCompilerProps<Parameters>,
  nodeOrder: GPUCommandGraphNode<Parameters>[],
  compiledNodes: CompiledNode<Parameters>[],
  transientBuffers: Map<GraphBufferHandle, Buffer>,
  transientTextures: Map<GraphTextureHandle, Texture>,
  bufferPlan: BufferTransientAllocation[],
  texturePlan: TextureTransientAllocation[]
): GPUCommandGraphCompilation<Parameters> {
  const logicalBuffers = Array.from(props.buffers.values());
  const importedBuffers = logicalBuffers.filter(buffer => !buffer.transient);
  const logicalTransientBuffers = logicalBuffers.filter(buffer => buffer.transient);
  const importedBufferBytes = sumSafeByteLengths(
    importedBuffers.map(buffer => buffer.byteLength),
    'imported buffer capacities'
  );
  const logicalTransientBytes = sumSafeByteLengths(
    logicalTransientBuffers.map(buffer => buffer.byteLength),
    'logical transient buffer capacities'
  );
  const logicalBufferBytes = addSafeByteLengths(
    importedBufferBytes,
    logicalTransientBytes,
    'logical buffer capacities'
  );
  const physicalTransientBytes = sumSafeByteLengths(
    bufferPlan.map(allocation => allocation.byteLength),
    'physical transient buffer capacities'
  );
  const reusedTransientBytes = Math.max(0, logicalTransientBytes - physicalTransientBytes);
  const logicalTextures = Array.from(props.textures.values());
  const importedTextures = logicalTextures.filter(texture => !texture.transient);
  const logicalTransientTextures = logicalTextures.filter(texture => texture.transient);
  const importedTextureBytes = sumSafeByteLengths(
    importedTextures.map(getTextureByteLength),
    'imported texture estimates'
  );
  const logicalTransientTextureBytes = sumSafeByteLengths(
    logicalTransientTextures.map(getTextureByteLength),
    'logical transient texture estimates'
  );
  const logicalTextureBytes = addSafeByteLengths(
    importedTextureBytes,
    logicalTransientTextureBytes,
    'logical texture estimates'
  );
  const physicalTransientTextureBytes = sumSafeByteLengths(
    texturePlan.map(allocation => allocation.byteLength),
    'physical transient texture estimates'
  );
  const reusedTransientTextureBytes = Math.max(
    0,
    logicalTransientTextureBytes - physicalTransientTextureBytes
  );
  const stats: GPUCommandGraphStats = {
    nodeOrder: nodeOrder.map(node => node.id),
    importedBufferCount: importedBuffers.length,
    importedBufferBytes,
    logicalBufferCount: logicalBuffers.length,
    logicalBufferBytes,
    logicalTransientBufferCount: logicalTransientBuffers.length,
    physicalTransientBufferCount: bufferPlan.length,
    logicalTransientBytes,
    physicalTransientBytes,
    reusedTransientBytes,
    reusePercentage:
      logicalTransientBytes > 0 ? (reusedTransientBytes / logicalTransientBytes) * 100 : 0,
    importedTextureCount: importedTextures.length,
    importedTextureBytes,
    logicalTextureCount: logicalTextures.length,
    logicalTextureBytes,
    logicalTransientTextureCount: logicalTransientTextures.length,
    physicalTransientTextureCount: texturePlan.length,
    logicalTransientTextureBytes,
    physicalTransientTextureBytes,
    reusedTransientTextureBytes,
    textureReusePercentage:
      logicalTransientTextureBytes > 0
        ? (reusedTransientTextureBytes / logicalTransientTextureBytes) * 100
        : 0,
    logicalResourceBytes: addSafeByteLengths(
      logicalBufferBytes,
      logicalTextureBytes,
      'logical resource estimates'
    ),
    physicalTransientResourceBytes: addSafeByteLengths(
      physicalTransientBytes,
      physicalTransientTextureBytes,
      'physical transient resource estimates'
    )
  };
  const preflight = getGPUCommandGraphPreflightReport(
    props.device,
    logicalBuffers,
    nodeOrder,
    props.kernelMetadata
  );

  return {
    device: props.device,
    id: props.id,
    buffers: new Map(props.buffers),
    textures: new Map(props.textures),
    externalTextures: new Map(props.externalTextures),
    compiledNodes,
    transientBuffers,
    transientTextures,
    bufferTransientAllocations: bufferPlan,
    textureTransientAllocations: texturePlan,
    stats,
    preflight
  };
}

function summarizeResource(resource: GraphResourceUse): GPUCommandGraphResourceSummary {
  if ('buffer' in resource) {
    const buffer = resource.buffer;
    const view = 'buffer' in buffer ? buffer : undefined;
    return Object.freeze({
      id: view ? view.buffer.id : (buffer as GraphBufferHandle).id,
      kind: 'buffer',
      usage: resource.usage,
      byteOffset: view?.byteOffset ?? 0,
      byteLength: view
        ? view.length === 0
          ? 0
          : (view.length - 1) * view.byteStride + view.rowByteLength
        : (buffer as GraphBufferHandle).byteLength,
      ...(view ? {format: view.format, length: view.length} : {})
    });
  }
  const texture = 'texture' in resource ? resource.texture : resource.externalTexture;
  return Object.freeze({
    id: 'texture' in texture ? texture.texture.id : texture.id,
    kind: 'externalTexture' in resource ? 'external-texture' : 'texture',
    usage: resource.usage,
    width: texture.width,
    height: texture.height,
    ...('texture' in texture
      ? {
          baseMipLevel: texture.baseMipLevel,
          baseArrayLayer: texture.baseArrayLayer,
          mipLevelCount: texture.mipLevelCount,
          arrayLayerCount: texture.arrayLayerCount,
          aspect: texture.aspect
        }
      : {}),
    ...('format' in texture ? {format: texture.format, depth: texture.depth} : {})
  });
}

function getGPUCommandGraphPreflightReport<Parameters>(
  device: Device,
  buffers: GraphBufferHandle[],
  nodes: GPUCommandGraphNode<Parameters>[],
  kernelMetadata: GPUCommandGraphCompileOptions['kernelMetadata']
): GPUCommandGraphPreflightReport {
  const nodeReports = nodes.map(node => {
    const workload = node.workload ?? {};
    const kernel = kernelMetadata && node.type === 'compute' ? node.kernel : undefined;
    return Object.freeze({
      id: node.id,
      ...(node.description === undefined ? {} : {description: node.description}),
      type: node.type,
      ...(kernel && {
        kernel: Object.freeze({
          entryPoint: kernel.entryPoint,
          workgroupSize: Object.freeze([...kernel.workgroupSize] as const),
          bindings: Object.freeze(
            kernel.bindings.map(({name, type, group, location}) =>
              Object.freeze({name, type, group, location})
            )
          ),
          ...(kernelMetadata === 'source' && kernel.source !== undefined
            ? {source: kernel.source}
            : {})
        })
      }),
      resources: Object.freeze((node.resources ?? []).map(summarizeResource)),
      ...(workload.operation ? {operation: workload.operation} : {}),
      ...(workload.variant ? {variant: workload.variant} : {}),
      ...(node.publication ? {publication: Object.freeze({...node.publication})} : {}),
      ...(node.condition
        ? {
            condition: Object.freeze(
              node.condition.source === 'cpu'
                ? {id: node.condition.id, source: 'cpu' as const, mode: 'skip' as const}
                : {
                    id: node.condition.id,
                    source: 'gpu' as const,
                    mode: 'indirect' as const,
                    bufferId: node.condition.buffer.id,
                    byteOffset: node.condition.byteOffset ?? 0
                  }
            )
          }
        : {}),
      commandCount: workload.commandCount ?? 0,
      maximumWorkgroupCount: workload.maximumWorkgroupCount ?? 0,
      maximumInvocationCount: workload.maximumInvocationCount ?? 0,
      readByteLength: workload.readByteLength ?? 0,
      writeByteLength: workload.writeByteLength ?? 0
    });
  });
  const largestBufferByteLength = buffers.reduce(
    (maximum, buffer) => Math.max(maximum, buffer.byteLength),
    0
  );
  const largestStorageBufferBindingByteLength = nodes.reduce((maximum, node) => {
    for (const resource of node.resources ?? []) {
      if (
        isGraphBufferUse(resource) &&
        (resource.usage === 'storage-read' ||
          resource.usage === 'storage-write' ||
          resource.usage === 'storage-read-write')
      ) {
        maximum = Math.max(maximum, getStorageBindingRange(resource.buffer).size);
      }
    }
    return maximum;
  }, 0);
  const sum = (key: keyof (typeof nodeReports)[number]): number =>
    nodeReports.reduce((total, node) => {
      const value = node[key];
      return typeof value === 'number'
        ? addSafeByteLengths(total, value, 'workload estimates')
        : total;
    }, 0);
  return Object.freeze({
    nodes: Object.freeze(nodeReports),
    annotatedNodeCount: nodes.filter(node => node.workload !== undefined).length,
    conditionalNodeCount: nodes.filter(node => node.condition !== undefined).length,
    commandCount: sum('commandCount'),
    maximumWorkgroupCount: sum('maximumWorkgroupCount'),
    maximumInvocationCount: sum('maximumInvocationCount'),
    readByteLength: sum('readByteLength'),
    writeByteLength: sum('writeByteLength'),
    largestBufferByteLength,
    largestStorageBufferBindingByteLength,
    maxBufferByteLength: device.limits.maxBufferSize,
    maxStorageBufferBindingByteLength: device.limits.maxStorageBufferBindingSize,
    fitsDeviceLimits:
      largestBufferByteLength <= device.limits.maxBufferSize &&
      largestStorageBufferBindingByteLength <= device.limits.maxStorageBufferBindingSize
  });
}

/** Returns the underlying logical buffer for either a handle or typed data view. @internal */
export function getBufferHandle(buffer: GraphBufferHandle | GraphDataView): GraphBufferHandle {
  return 'buffer' in buffer ? buffer.buffer : buffer;
}

/** Returns the underlying logical texture for either a handle or subresource view. @internal */
export function getTextureHandle(
  texture: GraphTextureHandle | GraphTextureView
): GraphTextureHandle {
  return 'texture' in texture ? texture.texture : texture;
}

/** Narrows a declared resource use to a buffer use. @internal */
export function isGraphBufferUse(resource: GraphResourceUse): resource is GraphBufferUse {
  return 'buffer' in resource;
}

/** Narrows a declared resource use to an ordinary texture use. @internal */
export function isGraphTextureUse(resource: GraphResourceUse): resource is GraphTextureUse {
  return 'texture' in resource;
}

/**
 * Rejects storage bindings that WebGPU would consider writable aliases inside one shader pass.
 *
 * Graph data views are exposed through aligned binding ranges. Two logically adjacent views can
 * therefore alias at binding granularity even when their rows do not overlap.
 *
 * @internal
 */
export function validateGraphNodeBufferBindingAliasing<Parameters>(
  node: GPUCommandGraphNode<Parameters>
): void {
  if (node.type === 'copy') return;
  const storageUses = (node.resources ?? []).filter(
    (resource): resource is GraphBufferUse =>
      isGraphBufferUse(resource) &&
      (resource.usage === 'storage-read' ||
        resource.usage === 'storage-write' ||
        resource.usage === 'storage-read-write')
  );
  for (let firstIndex = 0; firstIndex < storageUses.length; firstIndex++) {
    const first = storageUses[firstIndex];
    for (let secondIndex = firstIndex + 1; secondIndex < storageUses.length; secondIndex++) {
      const second = storageUses[secondIndex];
      if (
        first.buffer === second.buffer ||
        getBufferHandle(first.buffer) !== getBufferHandle(second.buffer) ||
        (!isBufferWriteUsage(first.usage) && !isBufferWriteUsage(second.usage))
      ) {
        continue;
      }
      const firstRange = getStorageBindingRange(first.buffer);
      const secondRange = getStorageBindingRange(second.buffer);
      if (
        firstRange.offset < secondRange.offset + secondRange.size &&
        secondRange.offset < firstRange.offset + firstRange.size
      ) {
        const buffer = getBufferHandle(first.buffer);
        throw new Error(
          `GPUCommandGraph node "${node.id}" has overlapping writable storage bindings for buffer "${buffer.id}" (${formatByteRange(firstRange)} and ${formatByteRange(secondRange)}). Bind the shared range once or align the views to non-overlapping storage binding ranges.`
        );
      }
    }
  }
}

function getStorageBindingRange(buffer: GraphBufferHandle | GraphDataView): {
  offset: number;
  size: number;
} {
  if (!('buffer' in buffer)) {
    return {offset: 0, size: buffer.byteLength};
  }
  const alignment = 256;
  const offset = Math.floor(buffer.byteOffset / alignment) * alignment;
  const prefixByteLength = buffer.byteOffset - offset;
  const viewByteLength =
    buffer.length === 0
      ? buffer.rowByteLength
      : (buffer.length - 1) * buffer.byteStride + buffer.rowByteLength;
  return {offset, size: prefixByteLength + Math.max(viewByteLength, buffer.rowByteLength)};
}

function formatByteRange(range: {offset: number; size: number}): string {
  return `${range.offset}–${range.offset + range.size} bytes`;
}

/** Returns whether an access observes existing buffer contents. */
function isBufferReadUsage(usage: GraphBufferUsage): boolean {
  return (
    usage === 'storage-read' ||
    usage === 'storage-read-write' ||
    usage === 'uniform' ||
    usage === 'copy-source' ||
    usage === 'indirect' ||
    usage === 'vertex' ||
    usage === 'index'
  );
}

/** Returns whether an access changes buffer contents. */
function isBufferWriteUsage(usage: GraphBufferUsage): boolean {
  return (
    usage === 'storage-write' || usage === 'storage-read-write' || usage === 'copy-destination'
  );
}

/** Returns whether an access observes existing texture contents. */
function isTextureReadUsage(usage: GraphTextureUsage): boolean {
  return (
    usage === 'sampled' ||
    usage === 'storage-read' ||
    usage === 'storage-read-write' ||
    usage === 'render-attachment' ||
    usage === 'copy-source'
  );
}

/** Returns whether an access may change texture contents. */
function isTextureWriteUsage(usage: GraphTextureUsage): boolean {
  return (
    usage === 'storage-write' ||
    usage === 'storage-read-write' ||
    usage === 'render-attachment' ||
    usage === 'copy-destination'
  );
}

/**
 * Infers hazards and returns a stable topological node order.
 *
 * Buffer hazards are conservative at whole-handle granularity. Texture hazards use overlapping
 * aspect, mip, and layer ranges. Explicit dependencies and inferred hazards share the same graph;
 * nodes that are otherwise independent retain insertion order.
 */
function getNodeOrder<Parameters>(
  nodes: GPUCommandGraphNode<Parameters>[]
): GPUCommandGraphNode<Parameters>[] {
  const nodeById = new Map(nodes.map(node => [node.id, node]));
  const dependencies = new Map<string, Set<string>>();
  const lastBufferWriter = new Map<GraphBufferHandle, string>();
  const activeBufferReaders = new Map<GraphBufferHandle, Set<string>>();
  const textureHistory = new Map<
    GraphTextureHandle,
    {nodeId: string; resource: GraphTextureUse}[]
  >();

  for (const node of nodes) {
    const nodeDependencies = new Set(node.dependsOn ?? []);
    for (const dependency of nodeDependencies) {
      if (!nodeById.has(dependency)) {
        throw new Error(
          `GPUCommandGraph node "${node.id}" depends on missing node "${dependency}"`
        );
      }
    }
    for (const resource of node.resources ?? []) {
      if (isGraphBufferUse(resource)) {
        const handle = getBufferHandle(resource.buffer);
        if (isBufferReadUsage(resource.usage)) {
          const writer = lastBufferWriter.get(handle);
          if (writer) {
            nodeDependencies.add(writer);
          }
          const readers = activeBufferReaders.get(handle) ?? new Set<string>();
          readers.add(node.id);
          activeBufferReaders.set(handle, readers);
        }
        if (isBufferWriteUsage(resource.usage)) {
          const writer = lastBufferWriter.get(handle);
          if (writer) {
            nodeDependencies.add(writer);
          }
          for (const reader of activeBufferReaders.get(handle) ?? []) {
            if (reader !== node.id) {
              nodeDependencies.add(reader);
            }
          }
          activeBufferReaders.set(handle, new Set());
          lastBufferWriter.set(handle, node.id);
        }
      } else if (isGraphTextureUse(resource)) {
        const handle = getTextureHandle(resource.texture);
        const history = textureHistory.get(handle) ?? [];
        for (const previous of history) {
          if (
            previous.nodeId !== node.id &&
            textureUsesOverlap(previous.resource, resource) &&
            ((isTextureReadUsage(resource.usage) && isTextureWriteUsage(previous.resource.usage)) ||
              (isTextureWriteUsage(resource.usage) &&
                (isTextureReadUsage(previous.resource.usage) ||
                  isTextureWriteUsage(previous.resource.usage))))
          ) {
            nodeDependencies.add(previous.nodeId);
          }
        }
        history.push({nodeId: node.id, resource});
        textureHistory.set(handle, history);
      }
    }
    nodeDependencies.delete(node.id);
    dependencies.set(node.id, nodeDependencies);
  }

  // Visit only outgoing edges when a node completes. Keep the existing insertion-ordered
  // waves: nodes unlocked by this wave are scheduled in the next one.
  const dependents = nodes.map(() => [] as number[]);
  const insertionIndex = new Map(nodes.map((node, index) => [node.id, index]));
  const remainingCounts = nodes.map(node => dependencies.get(node.id)!.size);
  for (const [index, node] of nodes.entries()) {
    for (const dependency of dependencies.get(node.id)!) {
      dependents[insertionIndex.get(dependency)!].push(index);
    }
  }
  let ready = remainingCounts.flatMap((count, index) => (count === 0 ? [index] : []));
  const ordered: GPUCommandGraphNode<Parameters>[] = [];
  while (ready.length) {
    const next: number[] = [];
    for (const index of ready) {
      ordered.push(nodes[index]);
      for (const dependent of dependents[index]) {
        if (--remainingCounts[dependent] === 0) next.push(dependent);
      }
    }
    ready = next.sort((left, right) => left - right);
  }
  if (ordered.length !== nodes.length) {
    throw new Error('GPUCommandGraph contains a dependency cycle');
  }
  return ordered;
}

/** Returns whether two uses refer to overlapping subresources of the same logical texture. */
function textureUsesOverlap(left: GraphTextureUse, right: GraphTextureUse): boolean {
  const leftHandle = getTextureHandle(left.texture);
  const rightHandle = getTextureHandle(right.texture);
  if (leftHandle !== rightHandle) {
    return false;
  }
  const leftRange = getTextureSubresourceRange(left.texture);
  const rightRange = getTextureSubresourceRange(right.texture);
  return (
    aspectsOverlap(leftRange.aspect, rightRange.aspect) &&
    intervalsOverlap(
      leftRange.baseMipLevel,
      leftRange.mipLevelCount,
      rightRange.baseMipLevel,
      rightRange.mipLevelCount
    ) &&
    intervalsOverlap(
      leftRange.baseArrayLayer,
      leftRange.arrayLayerCount,
      rightRange.baseArrayLayer,
      rightRange.arrayLayerCount
    )
  );
}

/** Normalizes a whole texture or view to the range used for hazard overlap tests. */
function getTextureSubresourceRange(texture: GraphTextureHandle | GraphTextureView): {
  aspect: GraphTextureAspect;
  baseMipLevel: number;
  mipLevelCount: number;
  baseArrayLayer: number;
  arrayLayerCount: number;
} {
  if ('texture' in texture) {
    return texture;
  }
  return {
    aspect: 'all',
    baseMipLevel: 0,
    mipLevelCount: texture.mipLevels,
    baseArrayLayer: 0,
    arrayLayerCount: texture.dimension === '3d' ? 1 : texture.depth
  };
}

/** Returns whether two depth/stencil aspect selections overlap. */
function aspectsOverlap(left: GraphTextureAspect, right: GraphTextureAspect): boolean {
  return left === 'all' || right === 'all' || left === right;
}

/** Returns whether two half-open integer intervals overlap. */
function intervalsOverlap(
  leftStart: number,
  leftCount: number,
  rightStart: number,
  rightCount: number
): boolean {
  return leftStart < rightStart + rightCount && rightStart < leftStart + leftCount;
}

/**
 * Assigns transient buffers to reusable physical allocations.
 *
 * The earliest available allocation is selected by smallest capacity. Capacity grows to the
 * largest assigned handle and usage flags are combined across all assigned handles.
 */
function getBufferTransientAllocationPlan<Parameters>(
  nodes: GPUCommandGraphNode<Parameters>[],
  buffers: Iterable<GraphBufferHandle>
): BufferTransientAllocation[] {
  const lifetimes = getResourceLifetimes(nodes, resource =>
    isGraphBufferUse(resource) ? getBufferHandle(resource.buffer) : null
  );
  // Each operation shares one retained-buffer list across all its command nodes. Find the
  // scope once, rather than visiting every chunk on every node in a chunked operation.
  const scopes = new Map<readonly GraphBufferHandle[], {firstUse: number; lastUse: number}>();
  nodes.forEach((node, nodeIndex) => {
    if (!node.retainedBuffers?.length) return;
    const scope = scopes.get(node.retainedBuffers);
    if (scope) scope.lastUse = nodeIndex;
    else scopes.set(node.retainedBuffers, {firstUse: nodeIndex, lastUse: nodeIndex});
  });
  // Logical operation inputs/results overlap even for multi-pass lowerings. Private command
  // scratch continues to use its precise command-level lifetime.
  for (const [buffers, scope] of scopes) {
    for (const buffer of buffers) {
      if (!buffer.transient) continue;
      const lifetime = lifetimes.get(buffer);
      lifetimes.set(buffer, {
        firstUse: Math.min(lifetime?.firstUse ?? scope.firstUse, scope.firstUse),
        lastUse: Math.max(lifetime?.lastUse ?? scope.lastUse, scope.lastUse)
      });
    }
  }
  const allocations: BufferTransientAllocation[] = [];
  const transientBuffers = Array.from(buffers)
    .filter(buffer => buffer.transient)
    .map(buffer => ({buffer, lifetime: lifetimes.get(buffer)}))
    .sort(
      (left, right) =>
        (left.lifetime?.firstUse ?? Number.MAX_SAFE_INTEGER) -
        (right.lifetime?.firstUse ?? Number.MAX_SAFE_INTEGER)
    );

  // Completed allocations enter a capacity-ordered pool. Each allocation changes heaps only
  // once per lifetime; a large set of simultaneously live chunks no longer causes full scans.
  type Candidate = {allocation: BufferTransientAllocation; index: number};
  const active = new GPUPlanningHeap<Candidate>(
    (left, right) => left.allocation.lastUse - right.allocation.lastUse || left.index - right.index
  );
  // Mappable staging buffers cannot combine their usages with storage/vertex buffers.
  const available = new Map<number, GPUPlanningHeap<Candidate>>();
  const getAvailable = (usage: number): GPUPlanningHeap<Candidate> => {
    const key = usage & (Buffer.MAP_READ | Buffer.MAP_WRITE);
    let pool = available.get(key);
    if (!pool) {
      pool = new GPUPlanningHeap<Candidate>(
        (left, right) =>
          left.allocation.byteLength - right.allocation.byteLength || left.index - right.index
      );
      available.set(key, pool);
    }
    return pool;
  };

  for (const {buffer, lifetime} of transientBuffers) {
    if (!lifetime) {
      continue;
    }
    while (active.peek() && active.peek()!.allocation.lastUse < lifetime.firstUse) {
      const completed = active.pop()!;
      getAvailable(completed.allocation.usage).push(completed);
    }
    let candidate = getAvailable(buffer.usage).pop();
    if (!candidate) {
      candidate = {
        allocation: {byteLength: 0, usage: 0, lastUse: -1, handles: []},
        index: allocations.length
      };
      allocations.push(candidate.allocation);
    }
    const {allocation} = candidate;
    allocation.byteLength = Math.max(allocation.byteLength, buffer.byteLength);
    allocation.usage |= buffer.usage;
    allocation.lastUse = lifetime.lastUse;
    allocation.handles.push(buffer);
    active.push(candidate);
  }
  return allocations;
}

/**
 * Assigns transient textures to descriptor-compatible physical allocations with disjoint
 * lifetimes. Unlike buffers, texture extent and sampling properties cannot grow during reuse.
 */
function getTextureTransientAllocationPlan<Parameters>(
  nodes: GPUCommandGraphNode<Parameters>[],
  textures: Iterable<GraphTextureHandle>
): TextureTransientAllocation[] {
  const lifetimes = getResourceLifetimes(nodes, resource =>
    isGraphTextureUse(resource) ? getTextureHandle(resource.texture) : null
  );
  const allocations: TextureTransientAllocation[] = [];
  const transientTextures = Array.from(textures)
    .filter(texture => texture.transient)
    .map(texture => ({texture, lifetime: lifetimes.get(texture)}))
    .sort(
      (left, right) =>
        (left.lifetime?.firstUse ?? Number.MAX_SAFE_INTEGER) -
        (right.lifetime?.firstUse ?? Number.MAX_SAFE_INTEGER)
    );

  for (const {texture, lifetime} of transientTextures) {
    if (!lifetime) {
      continue;
    }
    let allocation = allocations.find(
      candidate =>
        candidate.lastUse < lifetime.firstUse &&
        areTextureDescriptorsCompatible(candidate.descriptor, texture)
    );
    if (!allocation) {
      const descriptor = getNormalizedTextureDescriptor(texture);
      allocation = {
        descriptor,
        byteLength: getTextureByteLength(texture),
        lastUse: -1,
        handles: []
      };
      allocations.push(allocation);
    }
    allocation.descriptor.usage |= texture.usage;
    allocation.lastUse = lifetime.lastUse;
    allocation.handles.push(texture);
  }
  return allocations;
}

/** Returns inclusive first/last scheduled use indices for each referenced transient resource. */
function getResourceLifetimes<Parameters, Resource extends object>(
  nodes: GPUCommandGraphNode<Parameters>[],
  getResource: (resource: GraphResourceUse) => Resource | null
): Map<Resource, {firstUse: number; lastUse: number}> {
  const lifetimes = new Map<Resource, {firstUse: number; lastUse: number}>();
  nodes.forEach((node, nodeIndex) => {
    for (const resourceUse of node.resources ?? []) {
      const resource = getResource(resourceUse);
      if (!resource || !('transient' in resource) || !resource.transient) {
        continue;
      }
      const lifetime = lifetimes.get(resource);
      if (lifetime) {
        lifetime.lastUse = nodeIndex;
      } else {
        lifetimes.set(resource, {firstUse: nodeIndex, lastUse: nodeIndex});
      }
    }
  });
  return lifetimes;
}

/** Copies a logical texture handle into the mutable physical-allocation descriptor. */
function getNormalizedTextureDescriptor(texture: GraphTextureHandle): TransientTextureDescriptor {
  return {
    id: texture.id,
    format: texture.format,
    width: texture.width,
    height: texture.height,
    usage: texture.usage,
    dimension: texture.dimension,
    depth: texture.depth,
    mipLevels: texture.mipLevels,
    samples: texture.samples
  };
}

/** Returns whether a logical texture can reuse an existing physical texture allocation. */
function areTextureDescriptorsCompatible(
  descriptor: TransientTextureDescriptor,
  texture: GraphTextureHandle
): boolean {
  return (
    descriptor.format === texture.format &&
    descriptor.width === texture.width &&
    descriptor.height === texture.height &&
    descriptor.dimension === texture.dimension &&
    descriptor.depth === texture.depth &&
    descriptor.mipLevels === texture.mipLevels &&
    descriptor.samples === texture.samples
  );
}

/** Estimates all mip and sample storage for texture reuse statistics. */
function getTextureByteLength(texture: GraphTextureHandle): number {
  let byteLength = 0;
  for (let mipLevel = 0; mipLevel < texture.mipLevels; mipLevel++) {
    byteLength = addSafeByteLengths(
      byteLength,
      textureFormatDecoder.computeMemoryLayout({
        format: texture.format,
        width: Math.max(1, texture.width >> mipLevel),
        height: texture.dimension === '1d' ? 1 : Math.max(1, texture.height >> mipLevel),
        depth: texture.dimension === '3d' ? Math.max(1, texture.depth >> mipLevel) : texture.depth,
        byteAlignment: 1
      }).byteLength,
      `texture "${texture.id}" mip estimates`
    );
  }
  const sampledByteLength = byteLength * texture.samples;
  if (!Number.isSafeInteger(sampledByteLength)) {
    throw new Error(
      `GPUCommandGraph texture "${texture.id}" byte estimate exceeds safe integer range`
    );
  }
  return sampledByteLength;
}

/** Adds byte lengths without allowing silent precision loss in memory statistics. */
function addSafeByteLengths(left: number, right: number, label: string): number {
  const total = left + right;
  if (!Number.isSafeInteger(total)) {
    throw new Error(`GPUCommandGraph ${label} exceed safe integer range`);
  }
  return total;
}

/** Sums byte lengths without allowing silent precision loss in memory statistics. */
function sumSafeByteLengths(values: number[], label: string): number {
  return values.reduce((total, value) => addSafeByteLengths(total, value, label), 0);
}
