import type {GPUVectorLike} from '@luma.gl/graph/gpu-data';
import {getGPUVectorChunks, type GPUVectorChunk} from '@luma.gl/graph/gpu-data';

import type {
  Buffer,
  GPUClockCorrelation,
  CommandEncoder,
  ComputePass,
  Device,
  ExternalTexture,
  RenderPass,
  RenderPassProps,
  ComputeShaderLayout,
  Texture,
  TextureFormat,
  TextureView
} from '@luma.gl/core';
import type {DynamicBuffer, DynamicTexture} from '@luma.gl/core/dynamic';
import type {GPUVectorFormat} from '@luma.gl/graph/gpu-data';

/** Internal identity shared by graph-owned handles without importing the graph implementation. */
export type GPUCommandGraphOwner = {
  readonly id: string;
};

/**
 * Access mode for a buffer used by a command-graph node.
 *
 * The compiler uses this declaration to infer read-after-write, write-after-read, and
 * write-after-write dependencies. It also validates that the physical buffer has the required
 * WebGPU usage flag.
 */
export type GraphBufferUsage =
  | 'storage-read'
  | 'storage-write'
  | 'storage-read-write'
  | 'uniform'
  | 'copy-source'
  | 'copy-destination'
  | 'indirect'
  | 'vertex'
  | 'index';

/**
 * Access mode for a texture or texture view used by a command-graph node.
 *
 * Texture hazards are inferred only when the declared mip, layer, and aspect ranges overlap.
 */
export type GraphTextureUsage =
  | 'sampled'
  | 'storage-read'
  | 'storage-write'
  | 'storage-read-write'
  | 'render-attachment'
  | 'copy-source'
  | 'copy-destination';

/** Caller-owned buffer accepted as a fixed or per-encoding graph import. */
export type GraphImportedBuffer = Buffer | DynamicBuffer;

/** Caller-owned texture accepted as a fixed or per-encoding graph import. */
export type GraphImportedTexture = Texture | DynamicTexture;

/** One explicitly numbered frame-scoped texture binding. */
export type GraphFrameTextureBinding = {
  /** Caller-acquired texture valid for this encoding only. */
  texture: GraphImportedTexture;
  /** Strictly increasing application frame identifier for this compiled graph. */
  frameId: number;
};

/** Descriptor for one frame-scoped external-image binding. */
export type GraphExternalTextureDescriptor = {
  /** Graph-wide resource identifier. */
  id: string;
  /** Expected source width in pixels. */
  width: number;
  /** Expected source height in pixels. */
  height: number;
};

/** One explicitly numbered external-image binding valid for a single encoding. */
export type GraphExternalTextureBinding = {
  /** Fresh caller-acquired external texture for this encoding. */
  texture: ExternalTexture;
  /** Strictly increasing application frame identifier for this compiled graph. */
  frameId: number;
};

/** Descriptor for one imported or transient graph buffer. */
export type GraphBufferDescriptor = {
  /** Graph-wide resource identifier. */
  id: string;
  /** Required capacity in bytes. */
  byteLength: number;
  /** Bitwise union of the required luma.gl buffer usage flags. */
  usage: number;
};

/** Logical texture dimension supported by the command graph. */
export type GraphTextureDimension = '1d' | '2d' | '2d-array' | 'cube' | 'cube-array' | '3d';

/** Depth/stencil aspect selected by a {@link GraphTextureView}. */
export type GraphTextureAspect = 'all' | 'stencil-only' | 'depth-only';

/** Descriptor for one fixed-size imported or transient graph texture. */
export type GraphTextureDescriptor<Format extends TextureFormat = TextureFormat> = {
  /** Graph-wide resource identifier. */
  id: string;
  /** Physical texel format. */
  format: Format;
  /** Width of mip level zero. */
  width: number;
  /** Height of mip level zero. */
  height: number;
  /** Bitwise union of the required luma.gl texture usage flags. */
  usage: number;
  /** Texture dimension. Defaults to `'2d'`. */
  dimension?: GraphTextureDimension;
  /** Array-layer count or depth for a 3D texture. Defaults to `1`. */
  depth?: number;
  /** Number of mip levels. Defaults to `1`. */
  mipLevels?: number;
  /** Multisample count. Defaults to `1`. */
  samples?: number;
};

/** Fully defaulted texture descriptor used by graph internals. @internal */
export type NormalizedGraphTextureDescriptor<Format extends TextureFormat = TextureFormat> = {
  id: string;
  format: Format;
  width: number;
  height: number;
  usage: number;
  dimension: GraphTextureDimension;
  depth: number;
  mipLevels: number;
  samples: number;
};

/**
 * Opaque logical buffer tracked by a `GPUCommandGraph`.
 *
 * A handle describes capacity, usage, and ownership but does not expose a concrete buffer. The
 * concrete buffer is resolved while encoding a {@link CompiledGPUCommandGraph}.
 */
export class GraphBufferHandle {
  /** Graph-wide resource identifier. */
  readonly id: string;
  /** Required capacity in bytes. */
  readonly byteLength: number;
  /** Required luma.gl buffer usage flags. */
  readonly usage: number;
  /** Whether the graph owns and may alias the physical allocation. */
  readonly transient: boolean;
  /** @internal */
  readonly graph: GPUCommandGraphOwner;
  /** @internal */
  readonly defaultBuffer?: GraphImportedBuffer;

  /** @internal */
  constructor(
    graph: GPUCommandGraphOwner,
    descriptor: GraphBufferDescriptor,
    transient: boolean,
    defaultBuffer?: GraphImportedBuffer
  ) {
    this.graph = graph;
    this.id = descriptor.id;
    this.byteLength = descriptor.byteLength;
    this.usage = descriptor.usage;
    this.transient = transient;
    this.defaultBuffer = defaultBuffer;
  }
}

/**
 * Typed logical range within one {@link GraphBufferHandle}.
 *
 * A data view mirrors one fixed-width `GPUData` chunk: it carries layout metadata but does not own
 * the underlying buffer. Hazards remain buffer-granular, so two views of the same handle alias.
 */
export class GraphDataView<T extends GPUVectorFormat = GPUVectorFormat> {
  /** Logical buffer containing the range. */
  readonly buffer: GraphBufferHandle;
  /** Stored GPU value format. */
  readonly format: T;
  /** Number of logical rows. */
  readonly length: number;
  /** Byte offset of the first row in the logical buffer. */
  readonly byteOffset: number;
  /** Byte distance between consecutive rows. */
  readonly byteStride: number;
  /** Number of bytes occupied by one row. */
  readonly rowByteLength: number;

  /** @internal */
  constructor(
    buffer: GraphBufferHandle,
    props: {
      format: T;
      length: number;
      byteOffset: number;
      byteStride: number;
      rowByteLength: number;
    }
  ) {
    this.buffer = buffer;
    this.format = props.format;
    this.length = props.length;
    this.byteOffset = props.byteOffset;
    this.byteStride = props.byteStride;
    this.rowByteLength = props.rowByteLength;
  }
}

/**
 * Ordered graph data views that preserve one fixed-width `GPUVector`'s chunk boundaries.
 *
 * A vector view is metadata and an ordered list only. Nodes declare uses of individual
 * {@link GraphDataView} chunks so that the compiler continues to track physical buffer hazards.
 */
export class GraphVectorView<T extends GPUVectorFormat = GPUVectorFormat>
  implements GPUVectorLike<T, GraphDataView<T>>
{
  /** Canonical logical positions and physical views for every chunk. */
  readonly chunks: readonly GPUVectorChunk<GraphDataView<T>>[];
  /** Identifier supplied to `GPUCommandGraph.importGPUVector`. */
  readonly id: string;
  /** Source vector name. */
  readonly name: string;
  /** Canonical format shared by every chunk. */
  readonly format: T;
  /** Total logical row count across all chunks. */
  readonly length: number;
  /** Total flattened value count across all chunks. */
  readonly valueLength: number;
  /** Source vector stride in format components. */
  readonly stride: number;
  /** Source vector byte stride. */
  readonly byteStride: number;
  /** Source vector bytes occupied by one row. */
  readonly rowByteLength: number;
  /** Imported chunks in source order. */
  readonly data: readonly GraphDataView<T>[];

  /** @internal */
  constructor(props: {
    id: string;
    name: string;
    format: T;
    length: number;
    valueLength: number;
    stride: number;
    byteStride: number;
    rowByteLength: number;
    data: readonly GraphDataView<T>[];
  }) {
    this.id = props.id;
    this.name = props.name;
    this.format = props.format;
    this.length = props.length;
    this.valueLength = props.valueLength;
    this.stride = props.stride;
    this.byteStride = props.byteStride;
    this.rowByteLength = props.rowByteLength;
    if (
      props.data.some(data => data.format !== props.format) ||
      props.data.reduce((length, data) => length + data.length, 0) !== props.length
    ) {
      throw new Error(
        `${props.id} length must equal its ordered source chunks, with matching formats`
      );
    }
    this.data = Object.freeze([...props.data]);
    this.chunks = getGPUVectorChunks(this.data);
  }
}

/**
 * Opaque logical texture tracked by a `GPUCommandGraph`.
 *
 * The descriptor is fixed at graph construction. Imported textures must match it exactly at each
 * encoding; transient textures are created and owned by the compiled graph.
 */
export class GraphTextureHandle<Format extends TextureFormat = TextureFormat> {
  /** Graph-wide resource identifier. */
  readonly id: string;
  /** Physical texel format. */
  readonly format: Format;
  /** Width of mip level zero. */
  readonly width: number;
  /** Height of mip level zero. */
  readonly height: number;
  /** Required luma.gl texture usage flags. */
  readonly usage: number;
  /** Logical texture dimension. */
  readonly dimension: GraphTextureDimension;
  /** Array-layer count or depth for a 3D texture. */
  readonly depth: number;
  /** Number of mip levels. */
  readonly mipLevels: number;
  /** Multisample count. */
  readonly samples: number;
  /** Whether the graph owns and may alias the physical allocation. */
  readonly transient: boolean;
  /** Whether every encoding requires a fresh, explicitly numbered frame binding. */
  readonly frameScoped: boolean;
  /** @internal */
  readonly graph: GPUCommandGraphOwner;
  /** @internal */
  readonly defaultTexture?: GraphImportedTexture;

  /** @internal */
  constructor(
    graph: GPUCommandGraphOwner,
    descriptor: NormalizedGraphTextureDescriptor<Format>,
    transient: boolean,
    defaultTexture?: GraphImportedTexture,
    frameScoped = false
  ) {
    this.graph = graph;
    this.id = descriptor.id;
    this.format = descriptor.format;
    this.width = descriptor.width;
    this.height = descriptor.height;
    this.usage = descriptor.usage;
    this.dimension = descriptor.dimension;
    this.depth = descriptor.depth;
    this.mipLevels = descriptor.mipLevels;
    this.samples = descriptor.samples;
    this.transient = transient;
    this.frameScoped = frameScoped;
    this.defaultTexture = defaultTexture;
  }
}

/**
 * Opaque frame-scoped external-image binding tracked by a `GPUCommandGraph`.
 *
 * External textures are sampled-only browser snapshots. They cannot be viewed, copied, stored,
 * attached, allocated, or destroyed by the graph.
 */
export class GraphExternalTextureHandle {
  /** Graph-wide resource identifier. */
  readonly id: string;
  /** Expected source width in pixels. */
  readonly width: number;
  /** Expected source height in pixels. */
  readonly height: number;
  /** @internal */
  readonly graph: GPUCommandGraphOwner;

  /** @internal */
  constructor(graph: GPUCommandGraphOwner, descriptor: GraphExternalTextureDescriptor) {
    this.graph = graph;
    this.id = descriptor.id;
    this.width = descriptor.width;
    this.height = descriptor.height;
  }
}

/** Subresource range selected by `GPUCommandGraph.createTextureView`. */
export type GraphTextureViewProps = {
  /** View dimension. Defaults to the dimension implied by the texture. */
  dimension?: GraphTextureDimension;
  /** Depth/stencil aspect. Defaults to `'all'`. */
  aspect?: GraphTextureAspect;
  /** First visible mip level. Defaults to `0`. */
  baseMipLevel?: number;
  /** Number of visible mip levels. Defaults to all remaining levels. */
  mipLevelCount?: number;
  /** First visible array layer. Defaults to `0`. */
  baseArrayLayer?: number;
  /** Number of visible array layers. Defaults to all remaining layers. */
  arrayLayerCount?: number;
};

/** Logical mip, layer, and aspect range within one graph texture. */
export class GraphTextureView<Format extends TextureFormat = TextureFormat> {
  /** Logical texture containing the selected range. */
  readonly texture: GraphTextureHandle<Format>;
  /** Physical texel format inherited from the texture. */
  readonly format: Format;
  /** View dimension. */
  readonly dimension: GraphTextureDimension;
  /** Selected depth/stencil aspect. */
  readonly aspect: GraphTextureAspect;
  /** First selected mip level. */
  readonly baseMipLevel: number;
  /** Number of selected mip levels. */
  readonly mipLevelCount: number;
  /** First selected array layer. */
  readonly baseArrayLayer: number;
  /** Number of selected array layers. */
  readonly arrayLayerCount: number;
  /** Width of the first selected mip. */
  readonly width: number;
  /** Height of the first selected mip. */
  readonly height: number;
  /** Depth or layer count of the selected range. */
  readonly depth: number;

  /** @internal */
  constructor(
    texture: GraphTextureHandle<Format>,
    props: Required<GraphTextureViewProps> & {width: number; height: number; depth: number}
  ) {
    this.texture = texture;
    this.format = texture.format;
    this.dimension = props.dimension;
    this.aspect = props.aspect;
    this.baseMipLevel = props.baseMipLevel;
    this.mipLevelCount = props.mipLevelCount;
    this.baseArrayLayer = props.baseArrayLayer;
    this.arrayLayerCount = props.arrayLayerCount;
    this.width = props.width;
    this.height = props.height;
    this.depth = props.depth;
  }
}

/** One buffer use declared by a graph node. */
export type GraphBufferUse = {
  /** Whole logical buffer or typed range whose physical buffer is used. */
  buffer: GraphBufferHandle | GraphDataView;
  /** Access performed by the node. */
  usage: GraphBufferUsage;
};

/** One texture or texture-view use declared by a graph node. */
export type GraphTextureUse = {
  /** Whole logical texture or selected subresource range used by the node. */
  texture: GraphTextureHandle | GraphTextureView;
  /** Access performed by the node. */
  usage: GraphTextureUsage;
};

/** One sampled-only external-image use declared by a graph node. */
export type GraphExternalTextureUse = {
  /** Frame-scoped external texture sampled by the node. */
  externalTexture: GraphExternalTextureHandle;
  /** External textures expose sampled access only. */
  usage: 'sampled';
};

/** One resource use declared by a graph node. */
export type GraphResourceUse = GraphBufferUse | GraphTextureUse | GraphExternalTextureUse;

/** Graph-owned texture attachments resolved into a framebuffer for a render node. */
export type GraphRenderPassAttachments = {
  /** Color attachment views in render-target order. */
  colorAttachments: GraphTextureView[];
  /** Optional single-sample resolve target corresponding to each color attachment. */
  resolveTargets?: (GraphTextureView | null)[];
  /** Optional depth/stencil attachment view. */
  depthStencilAttachment?: GraphTextureView;
};

/** Context available while compiling one graph node. */
export type GPUCommandGraphCompileContext = {
  /** WebGPU device that owns the graph. */
  device: Device;
};

/** Context shared by every executable graph node. */
export type GPUCommandGraphEncodeContext<Parameters> = {
  /** Caller-owned encoder receiving the graph's commands. */
  commandEncoder: CommandEncoder;
  /** Per-encoding application parameters. */
  parameters: Parameters;
  /** Resolves a logical buffer or data view to its concrete buffer. */
  getBuffer: (buffer: GraphBufferHandle | GraphDataView) => Buffer;
  /** Resolves a logical texture or view to its concrete texture. */
  getTexture: (texture: GraphTextureHandle | GraphTextureView) => Texture;
  /** Resolves and caches the concrete texture view for a logical texture or view. */
  getTextureView: (texture: GraphTextureHandle | GraphTextureView) => TextureView;
  /** Resolves a frame-scoped external-image handle to its concrete sampled binding. */
  getExternalTexture: (texture: GraphExternalTextureHandle) => ExternalTexture;
};

/** Compiled compute-pass callback. */
export type GPUCommandGraphComputeExecutable<Parameters> = {
  /** Records commands into the compute pass opened by the graph. */
  encode: (context: GPUCommandGraphEncodeContext<Parameters> & {computePass: ComputePass}) => void;
  /** Releases node-owned compiled resources. */
  destroy?: () => void;
};

/** Compiled render-pass callback. */
export type GPUCommandGraphRenderExecutable<Parameters> = {
  /**
   * Returns per-encoding render-pass options.
   *
   * A caller-owned framebuffer may be supplied only when the node does not declare graph-managed
   * attachments. External framebuffer textures do not participate in graph hazard inference.
   */
  getRenderPassProps?: (context: GPUCommandGraphEncodeContext<Parameters>) => RenderPassProps;
  /** Records commands into the render pass opened by the graph. */
  encode: (context: GPUCommandGraphEncodeContext<Parameters> & {renderPass: RenderPass}) => void;
  /** Releases node-owned compiled resources. */
  destroy?: () => void;
};

/** Compiled command-encoder callback used for copies and other pass-independent commands. */
export type GPUCommandGraphCopyExecutable<Parameters> = {
  /** Records commands directly into the caller-owned encoder. */
  encode: (context: GPUCommandGraphEncodeContext<Parameters>) => void;
  /** Releases node-owned compiled resources. */
  destroy?: () => void;
};

/** CPU state evaluated immediately before a node would record commands. */
export type GPUCommandGraphCPUCondition<Parameters> = {
  /** Stable identity used by diagnostics and application telemetry. */
  id: string;
  source: 'cpu';
  /** Returns whether the node should record commands for this encoding. */
  evaluate: (parameters: Parameters) => boolean;
};

/** GPU-written indirect dispatch whose x dimension may be zero to suppress compute work. */
export type GPUCommandGraphGPUIndirectCondition = {
  /** Stable identity used by diagnostics and application telemetry. */
  id: string;
  source: 'gpu';
  mode: 'indirect';
  /** Buffer containing a standard WebGPU `[x, y, z]` indirect dispatch command. */
  buffer: GraphBufferHandle;
  /** Aligned byte offset of the indirect dispatch command. Default `0`. */
  byteOffset?: number;
};

/** Supported conditional-execution mechanisms for compute nodes. */
export type GPUCommandGraphNodeCondition<Parameters> =
  | GPUCommandGraphCPUCondition<Parameters>
  | GPUCommandGraphGPUIndirectCondition;

/** Serializable condition metadata retained by graph preflight. */
export type GPUCommandGraphNodeConditionPreflight = {
  id: string;
  source: 'cpu' | 'gpu';
  mode: 'skip' | 'indirect';
  bufferId?: string;
  byteOffset?: number;
};

type GPUCommandGraphNodeBase<Condition> = {
  /** @internal Logical result buffers kept live across the containing operation. */
  retainedBuffers?: readonly GraphBufferHandle[];
  /** Optional plain-text explanation shown in debugging tools and retained in traces. */
  description?: string;
  /** Graph-wide node identifier. */
  id: string;
  /** Resources read or written by the node, used for validation and hazard inference. */
  resources?: GraphResourceUse[];
  /** Explicit predecessor node identifiers in addition to inferred resource dependencies. */
  dependsOn?: string[];
  /** Optional upper-bound work estimate used by graph preflight diagnostics. */
  workload?: GPUCommandGraphNodeWorkloadEstimate;
  /** Optional coherent-result boundary exposed by progressive graph executions. */
  publication?: GPUCommandGraphNodePublication;
  /** Optional condition controlling whether this node records or dispatches work. */
  condition?: Condition;
};

/** A coherent result boundary declared by one graph node. */
export type GPUCommandGraphNodePublication = {
  /** Application-defined identity for the result that became safe to consume. */
  id: string;
  /** Whether the result is an intermediate snapshot or the complete operation output. */
  completeness: 'partial' | 'complete';
};

/** Static upper-bound cost supplied by an operation when it adds a graph node. */
export type GPUCommandGraphNodeWorkloadEstimate = {
  /** Human-readable primitive or operation name, such as `GPUScan`. */
  operation?: string;
  /** Equivalent implementation variant used for adapter-specific performance calibration. */
  variant?: string;
  /** Number of direct or indirect dispatch/draw/copy commands encoded by this node. */
  commandCount?: number;
  /** Maximum workgroups dispatched when the operation can determine that bound. */
  maximumWorkgroupCount?: number;
  /** Maximum shader invocations when the operation can determine that bound. */
  maximumInvocationCount?: number;
  /** Upper-bound bytes read by the operation. */
  readByteLength?: number;
  /** Upper-bound bytes written by the operation. */
  writeByteLength?: number;
};

/** Serializable declared resource range used by a node; does not retain GPU objects. */
export type GPUCommandGraphResourceSummary = Readonly<{
  id: string;
  kind: 'buffer' | 'texture' | 'external-texture';
  baseMipLevel?: number;
  baseArrayLayer?: number;
  mipLevelCount?: number;
  arrayLayerCount?: number;
  aspect?: GraphTextureAspect;
  usage: GraphBufferUsage | GraphTextureUsage;
  byteLength?: number;
  byteOffset?: number;
  format?: string;
  length?: number;
  width?: number;
  height?: number;
  depth?: number;
}>;

/** Static description of a compute kernel supplied by a command node. */
export type GPUCommandGraphKernelMetadata = Readonly<{
  entryPoint: string;
  workgroupSize: readonly [number, number, number];
  bindings: readonly Readonly<
    Pick<ComputeShaderLayout['bindings'][number], 'name' | 'type' | 'group' | 'location'>
  >[];
  source?: string;
}>;

/** Controls which kernel details a compiled graph exposes to inspectors. */
export type GPUCommandGraphCompileOptions = {
  /** Collect declared kernel metadata. Use 'source' to also include WGSL text. */
  kernelMetadata?: 'layout' | 'source';
};

/** Immutable per-node workload entry in a compiled graph preflight report. */
export type GPUCommandGraphNodePreflight = Readonly<
  Required<Omit<GPUCommandGraphNodeWorkloadEstimate, 'operation' | 'variant'>> & {
    id: string;
    type: GPUCommandGraphNodeType;
    description?: string;
    resources?: readonly GPUCommandGraphResourceSummary[];
    kernel?: GPUCommandGraphKernelMetadata;
    operation?: string;
    variant?: string;
    publication?: Readonly<GPUCommandGraphNodePublication>;
    condition?: Readonly<GPUCommandGraphNodeConditionPreflight>;
  }
>;

/** Aggregated static workload bounds available before the graph is submitted. */
export type GPUCommandGraphPreflightReport = {
  readonly nodes: readonly GPUCommandGraphNodePreflight[];
  /** Number of scheduled nodes that supplied a workload estimate. */
  readonly annotatedNodeCount: number;
  /** Number of nodes carrying CPU or GPU conditional-execution metadata. */
  readonly conditionalNodeCount: number;
  readonly commandCount: number;
  readonly maximumWorkgroupCount: number;
  readonly maximumInvocationCount: number;
  readonly readByteLength: number;
  readonly writeByteLength: number;
  readonly largestBufferByteLength: number;
  readonly largestStorageBufferBindingByteLength: number;
  readonly maxBufferByteLength: number;
  readonly maxStorageBufferBindingByteLength: number;
  readonly fitsDeviceLimits: boolean;
};

/** Compute node compiled once and encoded into a graph-owned compute pass. */
export type GPUCommandGraphComputeNode<Parameters> = GPUCommandGraphNodeBase<
  GPUCommandGraphNodeCondition<Parameters>
> & {
  /** Node discriminator. */
  type: 'compute';
  /** Optional kernel details for graph inspection. */
  kernel?: GPUCommandGraphKernelMetadata;
  /** Creates reusable node resources and the encode callback. */
  compile: (context: GPUCommandGraphCompileContext) => GPUCommandGraphComputeExecutable<Parameters>;
  /** Creates reusable node resources through asynchronous backend compilation when available. */
  compileAsync?: (
    context: GPUCommandGraphCompileContext
  ) => Promise<GPUCommandGraphComputeExecutable<Parameters>>;
};

/** Render node compiled once and encoded into a graph-owned render pass. */
export type GPUCommandGraphRenderNode<Parameters> = GPUCommandGraphNodeBase<
  GPUCommandGraphCPUCondition<Parameters>
> & {
  /** Node discriminator. */
  type: 'render';
  /** Optional graph-managed render attachments. */
  attachments?: GraphRenderPassAttachments;
  /** Creates reusable node resources and the encode callback. */
  compile: (context: GPUCommandGraphCompileContext) => GPUCommandGraphRenderExecutable<Parameters>;
  /** Creates reusable node resources through asynchronous backend compilation when available. */
  compileAsync?: (
    context: GPUCommandGraphCompileContext
  ) => Promise<GPUCommandGraphRenderExecutable<Parameters>>;
};

/** Copy or pass-independent node compiled once and encoded directly on the command encoder. */
export type GPUCommandGraphCopyNode<Parameters> = GPUCommandGraphNodeBase<
  GPUCommandGraphCPUCondition<Parameters>
> & {
  /** Node discriminator. */
  type: 'copy';
  /** Creates reusable node resources and the encode callback. */
  compile: (context: GPUCommandGraphCompileContext) => GPUCommandGraphCopyExecutable<Parameters>;
  /** Creates reusable node resources through asynchronous backend compilation when available. */
  compileAsync?: (
    context: GPUCommandGraphCompileContext
  ) => Promise<GPUCommandGraphCopyExecutable<Parameters>>;
};

/** Any node accepted by a `GPUCommandGraph`. */
export type GPUCommandGraphNode<Parameters> =
  | GPUCommandGraphComputeNode<Parameters>
  | GPUCommandGraphRenderNode<Parameters>
  | GPUCommandGraphCopyNode<Parameters>;

/** Execution category of one scheduled graph node. */
export type GPUCommandGraphNodeType = GPUCommandGraphNode<unknown>['type'];

/** Device capabilities and limits that affect command-graph portability. */
export type GPUCommandGraphCapabilities = {
  /** Whether the device can collect GPU timestamp queries. */
  timestampQueries: boolean;
  /** Whether the created WebGPU device exposes subgroup operations. */
  subgroups: boolean;
  /** Whether the browser's WGSL implementation exposes stable subgroup identifiers. */
  subgroupId: boolean;
  /** Minimum subgroup size reported by the adapter, when available. */
  subgroupMinSize?: number;
  /** Maximum subgroup size reported by the adapter, when available. */
  subgroupMaxSize?: number;
  /** Whether adapter metadata identifies a CPU or fallback implementation. */
  softwareAdapter: boolean;
  /** Maximum size of one GPU buffer allocation. */
  maxBufferByteLength: number;
  /** Maximum range visible through one storage-buffer binding. */
  maxStorageBufferBindingByteLength: number;
  /** Maximum invocations in one compute workgroup. */
  maxComputeInvocationsPerWorkgroup: number;
  /** Maximum dispatched workgroups along one dimension. */
  maxComputeWorkgroupsPerDimension: number;
};

/** Resource-allocation and scheduling statistics for one compiled graph. */
export type GPUCommandGraphStats = {
  /** Stable topological node order used for encoding. */
  nodeOrder: string[];
  /** Number of imported logical buffer handles. */
  importedBufferCount: number;
  /** Sum of declared capacities for imported buffers. */
  importedBufferBytes: number;
  /** Total number of imported and transient logical buffer handles. */
  logicalBufferCount: number;
  /** Sum of declared capacities for all logical buffers. */
  logicalBufferBytes: number;
  /** Number of logical transient buffer handles used by nodes. */
  logicalTransientBufferCount: number;
  /** Number of physical transient buffers allocated after lifetime reuse. */
  physicalTransientBufferCount: number;
  /** Sum of the capacities of logical transient buffers. */
  logicalTransientBytes: number;
  /** Sum of physical transient buffer allocation capacities. */
  physicalTransientBytes: number;
  /** Logical buffer bytes avoided through allocation reuse. */
  reusedTransientBytes: number;
  /** Percentage of logical buffer bytes avoided through reuse. */
  reusePercentage: number;
  /** Number of imported logical texture handles. */
  importedTextureCount: number;
  /** Estimated bytes across imported logical textures. */
  importedTextureBytes: number;
  /** Total number of imported and transient logical texture handles. */
  logicalTextureCount: number;
  /** Estimated bytes across all logical textures. */
  logicalTextureBytes: number;
  /** Number of logical transient texture handles used by nodes. */
  logicalTransientTextureCount: number;
  /** Number of physical transient textures allocated after lifetime reuse. */
  physicalTransientTextureCount: number;
  /** Estimated bytes across all logical transient textures. */
  logicalTransientTextureBytes: number;
  /** Estimated bytes across physical transient texture allocations. */
  physicalTransientTextureBytes: number;
  /** Estimated logical texture bytes avoided through allocation reuse. */
  reusedTransientTextureBytes: number;
  /** Percentage of estimated logical texture bytes avoided through reuse. */
  textureReusePercentage: number;
  /** Sum of declared buffer capacities and estimated texture bytes. */
  logicalResourceBytes: number;
  /** Estimated bytes owned by physical transient buffer and texture allocations. */
  physicalTransientResourceBytes: number;
};

/** CPU encoding statistics captured synchronously for one scheduled node. */
export type GPUCommandGraphNodeEncodingStats = {
  /** Declared resources and ranges, retained from compilation for trace inspection. */
  resources?: readonly GPUCommandGraphResourceSummary[];
  /** Application-provided plain-text explanation of this node. */
  description?: string;
  /** Semantic operation name from the node workload annotation, when available. */
  operation?: string;
  /** CPU clock endpoints in milliseconds (performance.now, or Date.now fallback).
   * Not correlated with GPU timestamps. Optional for externally constructed reports. */
  cpuEncodeStartTimeMilliseconds?: number;
  cpuEncodeEndTimeMilliseconds?: number;
  /** Stable graph node identifier. */
  id: string;
  /** Node execution category. */
  type: GPUCommandGraphNodeType;
  /** CPU time spent resolving resources and recording this node. */
  cpuEncodeTimeMilliseconds: number;
  /** Whether the pass recorded a GPU timestamp pair. Copy nodes are currently CPU-only. */
  hasGPUTimestamps: boolean;
  /** Conditional-execution decision, present only for conditional nodes. */
  condition?: {
    id: string;
    source: 'cpu' | 'gpu';
    /** CPU predicates may skip encoding; GPU indirect predicates are resolved on the GPU. */
    outcome: 'executed' | 'skipped' | 'gpu-resolved';
  };
};

/** Synchronous statistics for one complete graph encoding. */
export type GPUCommandGraphEncodingStats = {
  /** CPU clock endpoints in milliseconds (performance.now, or Date.now fallback).
   * Not correlated with GPU timestamps. Optional for externally constructed reports. */
  cpuEncodeStartTimeMilliseconds?: number;
  cpuEncodeEndTimeMilliseconds?: number;
  /** CPU time spent resolving imports and recording all graph nodes. */
  cpuEncodeTimeMilliseconds: number;
  /** Number of nodes encoded. */
  nodeCount: number;
  /** Number of scheduled nodes whose CPU predicate suppressed command recording. */
  skippedNodeCount: number;
  /** Number of physical compute passes opened for the encoded compute nodes. */
  computePassCount: number;
  /** Number of compute nodes that reused an already-open compute pass. */
  coalescedComputeNodeCount: number;
  /** Number of compute or render nodes with a GPU timestamp pair. */
  timestampedNodeCount: number;
  /** Per-node CPU encoding statistics in scheduled order. */
  nodes: GPUCommandGraphNodeEncodingStats[];
};

/** CPU and optional GPU duration for one encoded node. */
export type GPUCommandGraphNodeTiming = GPUCommandGraphNodeEncodingStats & {
  /** GPU clock endpoints in milliseconds, without CPU or wall-clock correlation.
   * Absent without timestamp queries or on duration-only backends.
   * Graph endpoints enclose measured passes only, including gaps between them. */
  gpuStartTimeMilliseconds?: number;
  gpuEndTimeMilliseconds?: number;
  /** GPU execution duration, available only after an explicit timing read. */
  gpuTimeMilliseconds?: number;
};

/** Explicit timing report for one encoded graph. */
export type GPUCommandGraphTimingReport = {
  /** Optional approximate GPU-to-CPU alignment from this submission. Raw endpoints are unchanged. */
  clockCorrelation?: GPUClockCorrelation;
  /** GPU clock endpoints in milliseconds, without CPU or wall-clock correlation.
   * Absent without timestamp queries or on duration-only backends.
   * Graph endpoints enclose measured passes only, including gaps between them. */
  gpuStartTimeMilliseconds?: number;
  gpuEndTimeMilliseconds?: number;
  /** CPU clock endpoints in milliseconds (performance.now, or Date.now fallback).
   * Not correlated with GPU timestamps. Optional for externally constructed reports. */
  cpuEncodeStartTimeMilliseconds?: number;
  cpuEncodeEndTimeMilliseconds?: number;
  /** CPU time spent encoding the graph. */
  cpuEncodeTimeMilliseconds: number;
  /** Sum of available per-node GPU durations. */
  gpuTimeMilliseconds?: number;
  /** Per-node CPU and optional GPU durations in scheduled order. */
  nodes: GPUCommandGraphNodeTiming[];
};

/** Options supplied while encoding one compiled graph. */
export type GPUCommandGraphEncodeOptions<Parameters> = {
  /** Application data forwarded to every node encode callback. */
  parameters: Parameters;
  /**
   * Whether consecutive compute nodes may share a physical compute pass. Defaults to true.
   * Automatic encoder timestamp profiling always preserves a separate pass for each node.
   */
  coalesceComputePasses?: boolean;
  /** Per-encoding imported-buffer replacements keyed by graph resource ID. */
  buffers?: Record<string, GraphImportedBuffer>;
  /** Per-encoding imported-texture replacements keyed by graph resource ID. */
  textures?: Record<string, GraphImportedTexture>;
  /** Per-encoding frame-scoped texture bindings keyed by graph resource ID. */
  frameTextures?: Record<string, GraphFrameTextureBinding>;
  /** Per-encoding frame-scoped external-image bindings keyed by graph resource ID. */
  externalTextures?: Record<string, GraphExternalTextureBinding>;
};
